import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"ADR 0006 — History-based instance-switch affordance, not native menu","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0006-history-based-instance-switch-affordance.md"},"headers":[],"relativePath":"apps/mobile/adrs/0006-history-based-instance-switch-affordance.md","filePath":"apps/mobile/adrs/0006-history-based-instance-switch-affordance.md"}'),i={name:"apps/mobile/adrs/0006-history-based-instance-switch-affordance.md"};function s(r,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0006-—-history-based-instance-switch-affordance-not-native-menu" tabindex="-1">ADR 0006 — History-based instance-switch affordance, not native menu <a class="header-anchor" href="#adr-0006-—-history-based-instance-switch-affordance-not-native-menu" aria-label="Permalink to &quot;ADR 0006 — History-based instance-switch affordance, not native menu&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Decided in this repo directly during task 20.1&#39;s implementation — unlike ADRs 0001–0005, this one has no centrally-locked precedent to restate, because <code>sovereign-desktop</code>&#39;s equivalent mechanism doesn&#39;t transfer.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>sovereign-desktop</code> gets back to its onboarding/instance-manager page via a native OS menu item (&quot;Instances → Switch Instance…&quot;, ⌘⇧I), which navigates the WebView back to the local page with <code>?manage=1</code>. A mobile shell has no persistent menu bar — there&#39;s no equivalent chrome to put a menu item in, and the WebView otherwise fills the whole screen once an instance is loaded, per <a href="./0002-universal-one-binary-distribution.html">ADR 0002</a> and <a href="./0005-server-url-not-bundled-assets.html">ADR 0005</a>.</p><p>Task 20.1&#39;s review checklist still requires &quot;users can add, remove, and switch between at least two instances,&quot; so this shell needs <em>some</em> way to get from &quot;an instance is loaded full-screen&quot; back to the instance list, without inventing a persistent native toolbar (which would be a real, maintained piece of native UI — more shell-side product surface than <a href="./../../CONCEPT.html">CONCEPT.md</a>&#39;s &quot;no product features in the shell&quot; principle wants for a first pass).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The local onboarding page is pushed onto WebView history rather than replaced: <code>onboarding.ts</code>&#39;s <code>loadInstance()</code> calls <code>window.location.assign(url)</code>, not <code>.replace(url)</code>, when navigating to an instance. Standard platform back navigation then returns to it for free:</p><ul><li><strong>Android:</strong> Capacitor&#39;s default <code>BridgeActivity</code> already routes the hardware back button through the WebView&#39;s history stack before falling back to exiting the app — no custom code needed.</li><li><strong>iOS:</strong> WKWebView&#39;s <code>allowsBackForwardNavigationGestures</code> (edge-swipe) is enabled in <code>MainViewController.swift</code>&#39;s <code>capacitorDidLoad()</code> (not <code>AppDelegate.swift</code> — that file is unmodified; the bridge view controller subclass is where the live <code>webView</code> instance is actually reachable).</li></ul><p>The result: swiping back (iOS) or pressing hardware/gesture back (Android) from the root of a loaded instance returns to this shell&#39;s instance list, exactly where a user switching instances wants to land.</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>A persistent native toolbar with a &quot;Switch Instance&quot; button.</strong> Real, maintained native UI surface for both platforms, contradicting the minimal-shell philosophy for a first-pass task. Revisit only if user testing shows the back-gesture affordance is undiscoverable.</li><li><strong>A custom URL scheme deep link</strong> (e.g. <code>sovereignmobile://switch</code>) triggered from an injected floating button. Requires the same kind of always-present injected UI as the toolbar option, plus a native <code>WKUserScript</code>/<code>evaluateJavascript</code> injection pipeline that doesn&#39;t exist yet — more machinery than the outcome justifies here.</li></ul><h3 id="the-local-page-must-actively-handle-being-returned-to-not-just-exist" tabindex="-1">The local page must actively handle being returned to, not just exist <a class="header-anchor" href="#the-local-page-must-actively-handle-being-returned-to-not-just-exist" aria-label="Permalink to &quot;The local page must actively handle being returned to, not just exist&quot;">​</a></h3><p>Getting <code>location.assign()</code> and <code>allowsBackForwardNavigationGestures</code> right was not sufficient on its own — confirmed by testing the actual gesture against a real instance, twice over, for two distinct reasons layered on top of each other:</p><ol><li><strong>WKWebView&#39;s back/forward cache (bfcache) restores the local page&#39;s DOM exactly as it was left, without re-running <code>main.ts</code>&#39;s top-level <code>void boot()</code> call.</strong> Since <code>boot()</code> had already run to completion (and called <code>location.assign</code>) before the page was navigated away from, a bfcache-restored view showed only the frozen <code>&lt;p class=&quot;splash&quot;&gt;</code> markup forever — inert, no redirect, no instance list, nothing. The standard fix is listening for <code>pageshow</code> and checking <code>event.persisted</code>, which is <code>true</code> exactly when the page came back from bfcache rather than a fresh load.</li><li><strong>Even without bfcache, <code>boot()</code>&#39;s own logic didn&#39;t know a load was reached by going <em>back</em>.</strong> Nothing sets <code>?manage=1</code> on a plain back navigation, so a fresh (non-bfcache) reload of the local page would see <code>activeUrl !== null &amp;&amp; !manage</code> and immediately redirect forward again — bouncing the user straight back to the instance they just tried to leave, defeating the entire affordance. Fixed by checking the Navigation Timing API&#39;s <code>performance.getEntriesByType(&#39;navigation&#39;)[0].type</code> for <code>&#39;back_forward&#39;</code> and treating that the same as <code>?manage=1</code>: skip the redirect, render the instance manager instead.</li></ol><p>Both fixes live in <code>src/main.ts</code>. Neither is native code — this remains a TypeScript-only fix, consistent with the &quot;native only for glue a Capacitor plugin doesn&#39;t already cover&quot; rule.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>This is the shell&#39;s entire &quot;switch instance while an instance is loaded&quot; UX for v1.</strong> It is a genuine, if implicit, affordance — not self-evidently discoverable without a hint. Revisit if this becomes a support/usability problem once real users are on it (see <a href="./../../ROADMAP.html">ROADMAP.md</a> — nothing currently tracks a follow-up task for this, since it&#39;s unverified need, not a known gap).</li><li>Requires the one line of native customization to <code>MainViewController.swift</code> described above; Android needs no equivalent change.</li><li>Any future feature that also wants to navigate the WebView (e.g. a future deep-link handler) must also use <code>assign</code>, not <code>replace</code>, or it will silently break this affordance by clobbering the history entry the back gesture depends on.</li><li><strong>Verified working on iOS Simulator (2026-08-01)</strong> against a real instance (<code>sovereign.openfs.io</code>), after the <code>pageshow</code>/<code>back_forward</code> fix above: swiping back from a loaded instance reliably shows the instance manager (list, remove, add-another-instance form) rather than a dead splash screen, repeatably across multiple connect/back/reconnect cycles.</li><li><strong>Verified working on a real physical iPhone (2026-08-06).</strong> Built, signed, installed, and launched on a connected iPhone 15 Pro via <code>xcodebuild -allowProvisioningUpdates</code> + <code>xcrun devicectl</code>; a human tester performed the actual gesture (this agent cannot inject touches into physical hardware). A genuine edge-swipe — not Simulator&#39;s synthetic gesture injection — returned from the loaded <code>sovereign.openfs.io</code> instance to the instance manager on the first try. This is the strongest confirmation of this affordance yet, since it&#39;s the exact real-world input the mechanism was designed for. See <a href="./../epics/shell.html">docs/epics/shell.md</a> for the full session detail.</li><li><strong>Inconclusive on Android Emulator (2026-08-02) — not confirmed working, not confirmed broken</strong> at the time. Tested against the same real instance on a fresh arm64-v8a API 34 AVD. Results were inconsistent enough that none of them were trusted as the answer on their own: <ul><li>One attempt clearly reached the app (logcat showed <code>boot()</code> re-running and calling <code>Preferences.get(&#39;sovereign.activeUrl&#39;)</code>) and then hung indefinitely — the plugin call never returned, leaving the splash frozen. This coincided with the emulator&#39;s WebView sandboxed renderer process (<code>com.google.android.webview:sandboxed_process0</code>) being killed and respawned around the same time, visible in <code>logcat</code>, which points at emulator/renderer instability rather than a logic bug in <code>main.ts</code> — but this isn&#39;t proven either way.</li><li>Several later attempts (<code>adb shell input keyevent KEYCODE_BACK</code>, both single and repeated presses, plus an edge-swipe via <code>adb shell input swipe</code>) never reached the app at all — <code>GoogleInputMethodService</code> logged consuming the back-key event first every time, and no <code>Capacitor</code>-tagged log line appeared afterward.</li><li>A same-session retest with a demonstrably healthy, freshly-restarted app process still produced no observable navigation on either input method.</li></ul></li><li><strong>Partially resolved, partially reconfirmed broken on Android Emulator (2026-08-06, two separate passes).</strong> The first pass that day retested only the case where the WebView navigates to the remote instance via a user-initiated tap (typing a URL and tapping Connect) within an already-running process: with no text field focused before the back-press, 5 consecutive <code>KEYCODE_BACK</code> presses each reached the instance manager on the first try — after a fresh connect, after a row-tap switch back into an instance, and after removing an instance. Switching between two real instances (<code>sovereign.openfs.io</code> and a local <code>sovereign</code> dev server at <code>http://10.0.2.2:3000</code>, the emulator&#39;s address for the host&#39;s <code>localhost:3000</code>) was also confirmed via each server&#39;s own request log. This part <strong>is</strong> genuinely fixed: the prior 2026-08-02 inconclusiveness on this specific path traced to back-presses being sent while the URL text field still held keyboard focus, not an app bug. <ul><li><strong>A second, more thorough pass the same day found a real, distinct bug</strong> (since fixed — see below): the affordance reliably <strong>failed</strong> when the WebView reached the remote instance via <code>boot()</code>&#39;s automatic <code>location.assign()</code> on a cold app launch (i.e. after Android force-stops the app — or the OS kills it in the background — and the user reopens it) rather than via a user tap. Reproduced on a fully clean <code>pm clear</code> install: connect once, force-stop, relaunch (lands correctly on the saved instance&#39;s sign-in page), then back-press — <strong>failed 8 consecutive times</strong>, confirmed stuck on the same screen each time via screenshot. <strong>This is the opposite of an even earlier &quot;resolved&quot; claim in this section&#39;s prior revision — that revision tested only the working (user-tap) path and over-generalized from it; the specific case the original 2026-08-02 finding most plausibly represents (a real user reopening the app) was not actually retested until this second pass, and was still broken.</strong></li><li><strong>Root cause, found by instrumenting native code and testing each hypothesis empirically rather than guessing:</strong> the first theory — <code>adb shell dumpsys input_method</code> showed the WebView registered as the IME&#39;s <code>mServedView</code> immediately after the cold-launch redirect, with no field ever tapped — pointed at a lingering IME input connection. That turned out to be a <strong>correlation, not the cause</strong>: explicitly clearing WebView focus in <code>onPageFinished</code> (including repeated delayed retries, to rule out a hydration-timing race) did not fix it. Intercepting the back key earlier, in <code>Activity.dispatchKeyEvent</code>, revealed the real problem once instrumented with logging: <strong>the WebView&#39;s own <code>canGoBack()</code> reports <code>false</code> and <code>goBack()</code> silently no-ops in this state — even though <code>copyBackForwardList()</code> correctly shows two entries</strong> (the local page and the remote instance) <strong>with the current index past the first.</strong> This is a genuine WebView/ Chromium internal-state bug specific to this navigation pattern (an early, JS-triggered, cross-origin <code>location.assign()</code> during a cold app launch), not anything wrong with this shell&#39;s own history handling — <code>assign</code> vs <code>replace</code> was never the issue. Delaying the redirect until after the local page&#39;s own <code>load</code> event (in case this was a timing race with the page not yet &quot;committed&quot;) was tried and ruled out — <code>canGoBack()</code> stayed stuck at <code>false</code> regardless of how long the wait.</li><li><strong>Fix (2026-08-06, same day): bypass the broken history mechanism entirely.</strong> <code>MainActivity.java</code>&#39;s <code>dispatchKeyEvent</code> now checks the WebView&#39;s <em>current URL</em> (not its back-forward-list state) to detect &quot;a remote instance is loaded,&quot; and on back-press, explicitly <code>loadUrl()</code>s the known local manage URL (<code>https://localhost/?manage=1</code>) directly, rather than calling <code>goBack()</code> and trusting it to work. This sidesteps the WebView bug entirely instead of working around its specific trigger conditions. <strong>Verified against the exact prior repro — clean install, connect, force-stop, relaunch, back-press — across three independent clean installs, all succeeding on the first press.</strong> Also verified this doesn&#39;t regress the already-working paths: switching into a listed instance via row-tap, and back-press from that state, both still work.</li><li><strong>Notably, iOS never had this problem</strong>: the real-physical-iPhone pass on 2026-08-06 (see below) explicitly exercised connect → force-quit → relaunch → swipe-back, and the swipe worked on the first try — this was specific to Android&#39;s WebView, not a shared <code>main.ts</code> logic bug.</li><li><strong>Net effect:</strong> this affordance is confirmed working on both platforms, including the cold-relaunch case, as of 2026-08-06. See <a href="./../epics/shell.html">docs/epics/shell.md</a> for the up-to-date checklist entry and the full session&#39;s raw evidence trail (including the two dead-end hypotheses, kept for anyone who hits a similar-looking symptom later).</li></ul></li></ul>',18)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
